  and i.deleted_at is null
  and n.ingredient_id = i.id
  and n.locale = v.locale
  and n.household_id is null
  and n.deleted_at is null
  and n.is_display_name
  and n.normalized_name is distinct from normalize_text(v.name);

-- 4. The names. `source = curated` marks these as hand-written
--    rather than produced by the matcher, and household_id is
--    null because the catalog is global -- an alias learned
--    once resolves for every household (docs/INGREDIENTS.md).
--
--    The conflict target is spelled out rather than named:
--    ingredient_names_unique is a unique INDEX over an
--    expression, not a table constraint, so
--    `on conflict on constraint ...` does not compile against
--    it. normalized_name is a generated column, which may
--    appear in the inference list but not in the insert list.
insert into ingredient_names as n
  (ingredient_id, name, locale, is_display_name, household_id, source)
select i.id, v.name, v.locale, v.is_display_name, null, 'curated'
