  is_display_name = excluded.is_display_name,
  source          = excluded.source,
  deleted_at      = null
where n.ingredient_id   is distinct from excluded.ingredient_id
   or n.is_display_name is distinct from excluded.is_display_name
   or n.deleted_at is not null;

-- 5. Fail loudly rather than leaving a half-seeded catalog. A
